import com.google.gson.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.nio.file.*;
import java.util.*;

/** Execute the reviewed candidate programs before replacing their previously invalid bundled versions. */
public final class LegacyPokemonProgramRepairTest {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final Map<String,PokemonProfile> PROFILES=load();
    static Map<String,PokemonProfile> load(){try{var result=new HashMap<String,PokemonProfile>();for(String line:Files.readAllLines(Path.of("outputs/legacy-pokemon-repair-programs.jsonl"))){var r=JsonParser.parseString(line).getAsJsonObject();result.put(r.get("id").getAsString(),BundledCombatData.pokemon(r.getAsJsonObject("conversion").getAsJsonObject("combatEntry"),EffectRegistry.standard()));}return result;}catch(Exception e){throw new RuntimeException(e);}}
    static AbilityDefinition ability(String id){return PROFILES.get(id).abilities().getFirst();}
    static void check(boolean b,String why){GeneratedRuleBatch8Test.check(b,why);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static UUID active(ServerMatch m){return m.activePokemonView(A).pokemonId();}
    static CardInstance hand(ServerMatch m,String id){return ModernRuleRepair2Test.hand(m,A,id);}
    static ServerMatch game(AbilityDefinition a,EnergyType type,Map<String,String> names){return ModernEnergyRepairTest.game(DynamicPassiveModifierTest.plainTool(),List.of(a),GeneratedRuleBatch8Test.hit(100,false),type,0,names);}
    static void select(ServerMatch m,List<CardInstance> cards){var q=m.effectCardPrompt(A);m.submitEffectCards(A,q.resolutionId(),q.step(),cards.stream().map(CardInstance::instanceId).toList());}
    static void target(ServerMatch m,UUID target){var q=m.effectPokemonPrompt(A);m.chooseEffectPokemon(A,q.resolutionId(),q.step(),target);}
    public static void main(String[] args){for(var p:PROFILES.values()){p.attacks().forEach(AttackProgramRules::validate);p.abilities().forEach(ActivatedAbilityRules::validate);}conversion();regal();named();roar();portal();starbirth();magnet();javelin();System.out.println("LegacyPokemonProgramRepairTest passed: actual twelve candidate programs parse; physical discard/draw binding, shared VSTAR usage, forced turn endings, exact named hosts, basic Energy/type filtering, private deck search, top-six window and V-only Bench damage");}
    static void conversion(){for(int count:List.of(0,1,3)){var a=ability("swsh12-5_en_046");var m=game(a,EnergyType.PSYCHIC,Map.of());var chosen=m.privateView(A).hand().subList(0,count);int before=m.privateView(A).hand().size(),deck=m.privateView(A).deck().size();m.useAbility(A,active(m),a.id());select(m,chosen);check(m.privateView(A).discard().containsAll(chosen)&&m.privateView(A).hand().size()==before&&m.privateView(A).deck().size()==deck-count,"Conversion Star drew wrong actual discard count");check(!m.canUseAbility(A,m.benchPokemonView(A).getFirst().pokemonId(),a.id()),"VSTAR reuse on another source");}}
    static void regal(){for(String id:List.of("swsh12-5_en_098","swsh12-5a_en_054")){var a=ability(id);var m=game(a,EnergyType.METAL,Map.of());var old=List.copyOf(m.privateView(A).hand());int turn=m.turnNumber();m.useAbility(A,active(m),a.id());check(m.privateView(A).discard().containsAll(old)&&m.privateView(A).hand().size()==5&&m.currentPlayer().equals(B)&&m.turnNumber()==turn+1&&!m.hasPendingEffectChoice(),"Regal Stance failed disposal/draw/turn end");}}
    static void named(){for(String id:List.of("swsh12-5_en_069","swsh12-5a_en_015","swsh12-5a_en_020")){var a=ability(id);boolean discard=!id.endsWith("020");String name=discard?"Lunatone":"Latios";var m=game(a,EnergyType.PSYCHIC,Map.of("basic",name,"wrongmon",name+" ex"));var wrong=hand(m,"wrongmon");m.playBasicPokemonToBench(A,wrong.instanceId());UUID wrongId=PokemonIdentityTestSupport.logical(m,A,wrong.instanceId());var good=hand(m,"energy");var fire=hand(m,"wrong");var special=hand(m,"special");if(discard)m.discardHandCardsByEffect(A,A,List.of(good.instanceId(),fire.instanceId(),special.instanceId()));m.useAbility(A,active(m),a.id());var q=m.effectPokemonPrompt(A);check(q.targets().stream().noneMatch(t->t.pokemonId().equals(wrongId)),"Substring name matched a different Pokemon");reject(()->target(m,wrongId));target(m,m.benchPokemonView(A).getFirst().pokemonId());var cards=m.effectCardPrompt(A);check(cards.candidates().contains(good)&&!cards.candidates().contains(fire)&&!cards.candidates().contains(special),"Named attachment accepted wrong/Special Energy");select(m,List.of(good));check(m.benchPokemonView(A).getFirst().attachedEnergyIds().contains(good.instanceId())&&!m.canUseAbility(A,active(m),a.id()),"Attachment host or source usage wrong");}}
    static void roar(){for(boolean take:List.of(false,true)){var a=ability("swsh12-5a_en_048");var m=game(a,EnergyType.PSYCHIC,Map.of());var good=hand(m,"energy");PairedTrainerPlayTest.zone(m,A,"hand").remove(good);PairedTrainerPlayTest.zone(m,A,"deck").add(good);int turn=m.turnNumber();m.useAbility(A,active(m),a.id());check(m.currentPlayer().equals(A),"Roar ended before private search");var q=m.effectCardPrompt(A);check(q.minimum()==0&&q.candidates().contains(good)&&q.candidates().stream().allMatch(c->c.definitionId().equals("energy")),"Roar must allow hidden-zone fail to find, basic Psychic only");select(m,take?List.of(good):List.of());if(take){var host=m.effectAttachmentPrompt(A);m.chooseEffectAttachmentTarget(A,host.resolutionId(),host.step(),active(m));}check(m.currentPlayer().equals(B)&&m.turnNumber()==turn+1&&m.activePokemonView(A).attachedEnergyIds().contains(good.instanceId())==take,"Roar failed final turn end or attachment");}}
    static void portal(){var a=ability("swsh12-5a_en_067");var m=game(a,EnergyType.WATER,Map.of());check(!m.canUseAbility(A,active(m),a.id()),"Star Portal usable without public eligible Energy");var wrong=hand(m,"wrongmon");m.playBasicPokemonToBench(A,wrong.instanceId());var good=hand(m,"energy");var special=hand(m,"special");m.discardHandCardsByEffect(A,A,List.of(good.instanceId(),special.instanceId()));m.useAbility(A,active(m),a.id());check(m.effectCardPrompt(A).minimum()==1,"Public up-to attachment allowed zero");reject(()->select(m,List.of()));select(m,List.of(good));var q=m.effectAttachmentPrompt(A);UUID wrongId=PokemonIdentityTestSupport.logical(m,A,wrong.instanceId());check(!q.targets().contains(wrongId),"Portal offered a non-Water host");reject(()->m.assignEffectEnergyDistribution(A,q.resolutionId(),q.step(),good.instanceId(),wrongId));m.assignEffectEnergyDistribution(A,q.resolutionId(),q.step(),good.instanceId(),active(m));m.confirmEffectEnergyDistribution(A,q.resolutionId(),q.step());check(m.activePokemonView(A).attachedEnergyIds().contains(good.instanceId())&&!m.canUseAbility(A,m.benchPokemonView(A).getFirst().pokemonId(),a.id()),"Star Portal failed or reused VSTAR");}
    static void starbirth(){var a=ability("swsh12-5a_en_070");var m=game(a,EnergyType.COLORLESS,Map.of());int before=m.privateView(A).hand().size();m.useAbility(A,active(m),a.id());var q=m.effectCardPrompt(A);check(q.minimum()==1&&q.maximum()==2,"Unrestricted deck search wrongly allowed zero");reject(()->select(m,List.of()));var chosen=q.candidates().subList(0,2);select(m,chosen);check(m.privateView(A).hand().containsAll(chosen)&&m.privateView(A).hand().size()==before+2,"Starbirth search did not finish");}
    static void magnet(){var a=ability("swsh12-5a_en_018");var m=game(a,EnergyType.METAL,Map.of());var good=hand(m,"energy");var special=hand(m,"special");var wrong=hand(m,"wrong");var deck=PairedTrainerPlayTest.zone(m,A,"deck");PairedTrainerPlayTest.zone(m,A,"hand").removeAll(List.of(good,special,wrong));deck.addAll(List.of(good,special,wrong));var top=List.copyOf(deck.subList(Math.max(0,deck.size()-6),deck.size()));m.useAbility(A,active(m),a.id());var q=m.effectCardPrompt(A);check(new HashSet<>(q.inspectedCards()).equals(new HashSet<>(top))&&q.candidates().contains(good)&&!q.candidates().contains(special)&&!q.candidates().contains(wrong),"Giga Magnet window/filter wrong");select(m,List.of(good));var dist=m.effectAttachmentPrompt(A);m.assignEffectEnergyDistribution(A,dist.resolutionId(),dist.step(),good.instanceId(),active(m));m.confirmEffectEnergyDistribution(A,dist.resolutionId(),dist.step());check(m.privateView(A).deck().containsAll(List.of(special,wrong))&&m.activePokemonView(A).attachedEnergyIds().contains(good.instanceId()),"Top-six remainder or selected Energy lost");}
    static void javelin(){for(boolean isV:List.of(false,true)){var c=new GeneratedRuleBatch28Test.Config();c.attack=PROFILES.get("swsh12-5a_en_046").attacks().getFirst();c.energyType=EnergyType.PSYCHIC;c.defenderFamilies=isV?Set.of(PokemonFamily.V):Set.of();var m=GeneratedRuleBatch28Test.fixture(c);ModernRuleRepair2Test.pay(m,A,active(m),"energy",3);m.attack(A,c.attack.id());if(isV){var q=m.effectPokemonPrompt(A);check(q.targets().size()==1&&q.targets().getFirst().pokemonId().equals(m.benchPokemonView(B).getFirst().pokemonId()),"Javelin offered wrong position/family");target(m,m.benchPokemonView(B).getFirst().pokemonId());}check(m.activePokemonView(B).damage()==190&&m.benchPokemonView(B).getFirst().damage()==(isV?60:0)&&!m.hasPendingEffectChoice(),"Javelin lost active damage or hit a non-V Bench");}}
}
